PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

CREATE TABLE user_credential (
    user_id INTEGER NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_user_credential PRIMARY KEY (user_id),
    CONSTRAINT fk_user_credential_user_id_app_user FOREIGN KEY(user_id) REFERENCES app_user (user_id) ON DELETE CASCADE
);

CREATE TABLE auth_session (
    token_hash VARCHAR(64) NOT NULL,
    user_id INTEGER NOT NULL,
    expires_at DATETIME NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_auth_session PRIMARY KEY (token_hash),
    CONSTRAINT fk_auth_session_user_id_user_credential FOREIGN KEY(user_id) REFERENCES user_credential (user_id) ON DELETE CASCADE
);

CREATE INDEX ix_auth_session_expires_at ON auth_session (expires_at);

CREATE INDEX ix_auth_session_user_id ON auth_session (user_id);

